// ── Shared image fallback — used by BOTH getHardcoded() and handler() ──────
// Replaces any broken local paths (/park.jpg etc.) with reliable Unsplash URLs.
// Call this on every activity before returning it to the frontend.
function applyImageFallback(a) {
  const localPathPattern = /^\//; // catches /park.jpg, /festival.jpg, /trail.jpg, etc.
  const isBroken = !a.image || localPathPattern.test(a.image);
  if (!isBroken) return; // already has a real URL — leave it alone

  const t = (a.name + " " + (a.desc || "")).toLowerCase();

  if (t.includes("soccer") || t.includes("sport") || t.includes("tennis") || t.includes("basketball"))
    a.image = "https://images.unsplash.com/photo-1551958219-acbc91c19eb6?w=600&q=80";
  else if (t.includes("swim") || t.includes("pool") || t.includes("aquatic") || t.includes("splash"))
    a.image = "https://images.unsplash.com/photo-1560090995-57e2e7e9ff84?w=600&q=80";
  else if (t.includes("stem") || t.includes("robot") || t.includes("cod") || t.includes("tech") || t.includes("ai") || t.includes("lego") || t.includes("science") || t.includes("snapology"))
    a.image = "https://images.unsplash.com/photo-1581092921461-39b9d08a9b21?w=600&q=80";
  else if (t.includes("art") || t.includes("paint") || t.includes("craft") || t.includes("pottery") || t.includes("clay"))
    a.image = "https://images.unsplash.com/photo-1588497859490-85d1c17db96d?w=600&q=80";
  else if (t.includes("danc") || t.includes("ballet") || t.includes("music"))
    a.image = "https://images.unsplash.com/photo-1508700929628-666bc8bd84ea?w=600&q=80";
  else if (t.includes("hike") || t.includes("trail") || t.includes("nature") || t.includes("creek") || t.includes("canyon") || t.includes("preserve"))
    a.image = "https://images.unsplash.com/photo-1501854140801-50d01698950b?w=600&q=80";
  else if (t.includes("park") || t.includes("playground") || t.includes("garden") || t.includes("outdoor"))
    a.image = "https://images.unsplash.com/photo-1472162072942-cd5147eb3902?w=600&q=80";
  else if (t.includes("museum") || t.includes("discovery") || t.includes("exhibit") || t.includes("history"))
    a.image = "https://images.unsplash.com/photo-1554907984-15263bfd63bd?w=600&q=80";
  else if (t.includes("library") || t.includes("book") || t.includes("reading") || t.includes("storytime"))
    a.image = "https://images.unsplash.com/photo-1507842217343-583bb7270b66?w=600&q=80";
  else if (t.includes("farm") || t.includes("zoo") || t.includes("animal") || t.includes("petting") || t.includes("horse") || t.includes("ranch"))
    a.image = "https://images.unsplash.com/photo-1516467508483-a7212febe31a?w=600&q=80";
  else if (t.includes("trampoline") || t.includes("altitude") || t.includes("bounce"))
    a.image = "https://images.unsplash.com/photo-1599474924187-334a4ae5bd3c?w=600&q=80";
  else if (t.includes("camp") || t.includes("ymca") || t.includes("galileo") || t.includes("kidstrong"))
    a.image = "https://images.unsplash.com/photo-1530268729831-4b0b9e170218?w=600&q=80";
  else if (t.includes("farmers market") || t.includes("festival") || t.includes("fair"))
    a.image = "https://images.unsplash.com/photo-1533900298318-6b8da08a523e?w=600&q=80";
  else
    a.image = "https://images.unsplash.com/photo-1472162072942-cd5147eb3902?w=600&q=80";
}

function getDefaultImage(name, desc) {
  const t = (name + " " + (desc||"")).toLowerCase();
  if (t.includes("bowl"))                                      return DEFAULT_IMAGES.bowling;
  if (t.includes("skat"))                                      return DEFAULT_IMAGES.skating;
  if (t.includes("laser") || t.includes("lazer"))             return DEFAULT_IMAGES.laser;
  if (t.includes("climb"))                                     return DEFAULT_IMAGES.climbing;
  if (t.includes("trampoline") || t.includes("altitude"))     return DEFAULT_IMAGES.trampoline;
  if (t.includes("swim") || t.includes("pool") || t.includes("aquatic")) return DEFAULT_IMAGES.swimming;
  if (t.includes("library") || t.includes("storytime"))       return DEFAULT_IMAGES.library;
  if (t.includes("potter") || t.includes("clay"))             return DEFAULT_IMAGES.pottery;
  if (t.includes("ymca") || t.includes("community center"))   return DEFAULT_IMAGES.ymca;
  if (t.includes("ballet") || t.includes("dance"))            return DEFAULT_IMAGES.dance;
  if (t.includes("stem") || t.includes("coding") || t.includes("robot") || t.includes("tech") || t.includes("ai")) return DEFAULT_IMAGES.stem;
  if (t.includes("art") || t.includes("studio") || t.includes("paint")) return DEFAULT_IMAGES.art;
  if (t.includes("soccer") || t.includes("sport") || t.includes("tennis")) return DEFAULT_IMAGES.sports;
  if (t.includes("music") || t.includes("gymboree"))          return DEFAULT_IMAGES.music;
  if (t.includes("museum") || t.includes("discovery"))        return DEFAULT_IMAGES.museum;
  if (t.includes("gymnastic") || t.includes("little gym") || t.includes("kidstrong")) return DEFAULT_IMAGES.gymnastics;
  if (t.includes("toddler") || t.includes("infant") || t.includes("baby") || t.includes("safari") || t.includes("preschool")) return DEFAULT_IMAGES.toddler;
  if (t.includes("indoor") || t.includes("playground"))       return DEFAULT_IMAGES.indoor;
  if (t.includes("camp") || t.includes("galileo"))            return DEFAULT_IMAGES.camp;
  return DEFAULT_IMAGES.default;
}

// fetch available globally in Node 18+
const PHOTO_CACHE = new Map();

async function getPlacePhoto(name, address, apiKey) {
  // Skip generic addresses — they return wrong photos
  const hasStreet = address && /^\d+/.test(address.trim());
  if (!hasStreet) { return null; }
  const cacheKey = name;
  if (PHOTO_CACHE.has(cacheKey)) return PHOTO_CACHE.get(cacheKey);
  if (!apiKey) { PHOTO_CACHE.set(cacheKey, null); return null; }
  try {
    const findUrl = "https://places.googleapis.com/v1/places:searchText";
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 3000); // 3 second timeout
    
    const findRes = await fetch(findUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Goog-Api-Key": apiKey,
        "X-Goog-FieldMask": "places.photos,places.displayName"
      },
      body: JSON.stringify({ textQuery: name + " " + (address || "") + " CA", maxResultCount: 1 }),
      signal: controller.signal
    });
    clearTimeout(timeout);
    const findData = await findRes.json();
    const photoName = findData.places?.[0]?.photos?.[0]?.name;
    if (!photoName) { PHOTO_CACHE.set(cacheKey, null); return null; }
    // Route through proxy to avoid CORS/redirect issues
    const photoUrl = "/api/img?ref=" + encodeURIComponent(photoName);
    PHOTO_CACHE.set(cacheKey, photoUrl);
    return photoUrl;
  } catch(e) {
    console.warn("Photo fetch failed for", name, e.message);
    PHOTO_CACHE.set(cacheKey, null);
    return null;
  }
}



